import './cloud-sync.js';
import{MONEY_TRACKS,MONEY_CHAIN,MONEY_DIAGNOSTIC,recommendMoneyTrack,moneyChoiceIndex,freshMoneyChoiceIndex,createBlankMoneyLearner}from'./money-data.js?v=money1';

const $=s=>document.querySelector(s),storageKey='mathlab-money-v1',memory={};
function blankStore(){return{a:createBlankMoneyLearner(),b:createBlankMoneyLearner(),learner:'a'}}
function readStore(){try{return JSON.parse(localStorage.getItem(storageKey))||blankStore()}catch{return memory.data||blankStore()}}
let store=readStore(),learner=store.learner||'a',state=store[learner]||createBlankMoneyLearner(),hintLevel=0,errors=0,sessionMissionId=null,work={};
function ensureState(){const blank=createBlankMoneyLearner();state={...blank,...state,diagnostic:{...blank.diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...blank.evidence,...state.evidence},family:{...blank.family,...state.family}}}
function save(){state.updatedAt=new Date().toISOString();store={...readStore(),[learner]:state,learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}catch{$('#saveStatus').textContent='Progress lasts until this page closes.'}}
function saveLearnerChoice(){store={...readStore(),learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store))}catch{}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function feedback(text,type=''){const el=$('#feedback');el.textContent=text;el.className='feedback '+type}
function track(){return MONEY_TRACKS[state.track||'explorer']}
function done(i){return Boolean(state.missions[MONEY_CHAIN.missions[i].id]?.complete)}
function unlocked(i){return i===0||done(i-1)}
function mark(dim,independent=true){if(independent)state.evidence[dim]='independent';else if(state.evidence[dim]==='unknown')state.evidence[dim]='learning'}
function loadSession(id){sessionMissionId=id;const saved=state.sessions[id]||{errors:0,hints:0,work:{}};errors=Number(saved.errors)||0;hintLevel=Number(saved.hints)||0;work=saved.work||{}}
function saveSession(nextWork=work){if(!sessionMissionId)return;work=nextWork;state.sessions[sessionMissionId]={errors,hints:hintLevel,work};save()}
function miss(message){errors++;saveSession();feedback(message,'try')}
function complete(i,dims=[],pending=false,preview=false){const m=MONEY_CHAIN.missions[i];state.missions[m.id]={complete:!preview,preview,errors,hints:hintLevel,completedAt:new Date().toISOString(),track:state.track};dims.forEach(d=>mark(d,errors===0&&hintLevel===0&&!preview));if(pending){state.retestDue=Date.now()+20*60*60*1000;state.evidence.transfer=state.evidence.transfer==='unknown'?'learning':state.evidence.transfer}if(!preview&&i<4)state.activeMission=i+1;delete state.sessions[m.id];errors=0;hintLevel=0;work={};sessionMissionId=null;save();setTimeout(render,420)}
function hint(text){return hintLevel?`<div class="hint-box">${esc(text)}</div>`:''}
function controls(){return `<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>`}
function arrange(correct,others,seed){const values=[...new Set(others.filter(v=>v!==correct))],index=typeof seed==='number'?((seed%(values.length+1))+(values.length+1))%(values.length+1):moneyChoiceIndex(seed,values.length+1);values.splice(index,0,correct);return values}
function textChoices(correct,others,attr,seed=`${track().id}:${attr}`){return `<div class="answer-grid">${arrange(correct,others,seed).map(v=>`<button class="choice" data-${attr}="${v===correct?'correct':'wrong'}">${esc(v)}</button>`).join('')}</div>`}
function numberChoices(correct,others,attr,seed=`${track().id}:${attr}:${Number(work.index)||0}`){return `<div class="answer-grid number-choices">${arrange(correct,others,seed).map(v=>`<button class="choice" data-${attr}="${v}">${v}</button>`).join('')}</div>`}
function storyCard(text,label='THE SITUATION'){const parts=text.split(/(?<=[.!?])\s+/);return `<div class="story-card"><small>${label}</small>${parts.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`}
function planFlow(steps,current=0){return `<div class="plan-flow">${steps.map((s,i)=>`<div class="plan-step ${i<current?'done':i===current?'current':''}"><span>${i+1}</span><strong>${i<current?work.answers?.[i]??'✓':i===current?'?':'…'}</strong><small>${esc(s.prompt)}</small></div>`).join('<b>→</b>')}</div>`}

function renderDiagnostic(){const d=state.diagnostic;if(d.index>=MONEY_DIAGNOSTIC.length){state.track=state.track||recommendMoneyTrack(d.score);renderTrack();const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><p class="microcopy">This chooses useful money-decision challenges. It is not a grade label.</p><button class="primary" data-action="start">Build a balanced budget →</button></div>`;return}const q=MONEY_DIAGNOSTIC[d.index];$('#activity').innerHTML=`<div class="diagnostic-progress"><span style="width:${d.index/MONEY_DIAGNOSTIC.length*100}%"></span></div><p class="eyebrow">QUESTION ${d.index+1} OF ${MONEY_DIAGNOSTIC.length}</p><h3>${esc(q.prompt)}</h3><div class="answer-grid">${q.choices.map((x,i)=>`<button class="choice" data-diagnostic="${i}">${esc(x)}</button>`).join('')}</div><p class="microcopy">No timer. Explain why the choice fits the available money and the stated priority.</p>`;document.querySelectorAll('[data-diagnostic]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.diagnostic)===q.answer;d.answers.push({id:q.id,correct});if(correct)d.score++;d.index++;feedback(correct?'That matches the money situation.':q.why,correct?'good':'try');save();setTimeout(()=>{feedback('');render()},450)})}
function renderPlan(){const p=track().budget,index=Number(work.index)||0,answers=work.answers||[];if(index<p.steps.length){const step=p.steps[index];$('#activity').innerHTML=`<p class="eyebrow">INCOME → PLANNED JOBS → MONEY LEFT</p><h3>${esc(step.prompt)}</h3>${storyCard(p.story)}${planFlow(p.steps,index)}${numberChoices(step.answer,step.decoys,'budget-answer')}${controls()}${hint(index===0?'Begin with the income actually available. If tax is named, find net income before planning.':'Use the previous remainder. Each dollar can have only one job.')}`;document.querySelectorAll('[data-budget-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.budgetAnswer)===step.answer){work={...work,index:index+1,answers:[...answers,step.answer]};saveSession();feedback('That amount fits the budget so far.','good');setTimeout(renderMission,350)}else miss('Check the income available, then subtract each planned job exactly once.')});return}$('#activity').innerHTML=`<p class="eyebrow">PROVE THE COMPLETE BUDGET</p><h3>${esc(p.equation)}</h3>${storyCard(p.story)}${planFlow(p.steps,p.steps.length)}${textChoices(p.proof,p.decoys,'budget-proof')}${controls()}${hint('A strong proof starts with available income, names every job, and checks that the jobs add back to the same total.')}`;document.querySelectorAll('[data-budget-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.budgetProof==='correct'){feedback('Yes. Every dollar has one job and the plan balances.','good');complete(1,['budget'])}else miss('Reject a plan that ignores taxes, duplicates money, or assigns more than the available income.')})}
function renderDecision(){const p=track().decision;if(!work.choice){$('#activity').innerHTML=`<p class="eyebrow">STEP 1 · FOLLOW THE STATED PRIORITY</p><h3>Which action best follows the need or goal in this situation?</h3>${storyCard(p.story,'THE CHOICE')}${textChoices(p.choice,p.choiceDecoys,'decision-choice')}${controls()}${hint('A budget choice is not automatically right for everyone. Use the priority stated in this exact situation.')}`;document.querySelectorAll('[data-decision-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.decisionChoice==='correct'){work={...work,choice:true};saveSession();feedback('That action follows the stated priority. Now name the tradeoff.','good');setTimeout(renderMission,350)}else miss('Check which option protects the stated need or moves the named goal forward.')});return}$('#activity').innerHTML=`<p class="eyebrow">STEP 2 · NAME WHAT WAITS AND WHY</p><h3>Which explanation includes both the reason and the opportunity cost?</h3>${storyCard(p.story,'THE CHOICE')}${textChoices(p.answer,p.decoys,'decision-answer')}${controls()}${hint('Name why the chosen action fits the priority, then state what must be delayed or given up.')}`;document.querySelectorAll('[data-decision-answer]').forEach(b=>b.onclick=()=>{if(b.dataset.decisionAnswer==='correct'){feedback('Yes. You connected the decision to its priority and named what must wait.','good');complete(2,['tradeoff'])}else miss('A complete explanation must contain both parts: why this choice comes first and what cannot happen now.')})}
function renderRepair(){const p=track().repair;if(!work.gap){$('#activity').innerHTML=`<p class="eyebrow">STEP 1 · MEASURE THE BUDGET GAP</p><h3>By exactly how many dollars does this plan exceed the available income?</h3>${storyCard(p.story,'A PROPOSED BUDGET')}${numberChoices(p.gap,p.gapDecoys,'gap-answer',`${track().id}:repair-gap`)}${controls()}${hint('Add all assigned jobs. Then subtract the available income from that total. The difference is the gap.')}`;document.querySelectorAll('[data-gap-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.gapAnswer)===p.gap){work={...work,gap:true};saveSession();feedback(`The plan is $${p.gap} over budget. Now make a repair that closes exactly that gap.`,'good');setTimeout(renderMission,350)}else miss('Compare the total assigned jobs with the income actually available. Do not compare only one category with income.')});return}$('#activity').innerHTML=`<p class="eyebrow">STEP 2 · CLOSE THE EXACT GAP</p><h3>Which change really makes the new total equal the available income?</h3>${storyCard(p.story,'A PROPOSED BUDGET')}<div class="reasonableness-card"><strong>Check three things</strong><span>Available income</span><span>Total planned jobs</span><span>Exact change needed: $${p.gap}</span></div>${textChoices(p.answer,p.decoys,'repair-answer')}${controls()}${hint('The repair must change real spending, saving, giving, or income by the exact gap. Renaming the shortage does not balance anything.')}`;document.querySelectorAll('[data-repair-answer]').forEach(b=>b.onclick=()=>{if(b.dataset.repairAnswer==='correct'){feedback('Exactly. You measured the gap and chose a repair that closes it.','good');complete(3,['repair'],true)}else miss(`The plan is still $${p.gap} over unless a real category or income changes by that amount.`)})}
function freshSteps(p){return p.steps.map((answer,i)=>({prompt:i===0?'Find the first amount remaining.':i===p.steps.length-1?'Find the final amount available.':'Use that remainder for the next budget job.',answer,decoys:[answer+p.steps[0],Math.abs(answer-(p.steps[i-1]||1))]}))}
function renderFresh(){const due=state.retestDue||Date.now()+20*60*60*1000,ready=Date.now()>=due;if(!ready&&!state.previewFresh){const hours=Math.max(1,Math.ceil((due-Date.now())/3600000)),name=learner==='a'?'Ella':'Mila';$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the budget plan has faded from memory.</strong><p>About ${hours} hours remain. Waiting checks whether ${name} can balance a new situation without copying today’s amounts.</p><button class="secondary" data-action="preview">Preview for family review</button><p class="microcopy">The preview uses a changed budget. It will not count as delayed evidence or earn credits.</p></div>`;return}const p=ready?track().fresh.challenge:track().fresh.preview,steps=freshSteps(p),index=Number(work.index)||0,answers=work.answers||[];if(!work.model){$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · BUILD A NEW BUDGET':'FAMILY PREVIEW · MODEL FIRST'}</p><h3>Which complete model matches the available income and every planned job?</h3>${storyCard(p.story)}${textChoices(p.model,p.modelDecoys,'fresh-model',freshMoneyChoiceIndex(track().id,'model',0,ready,3))}${controls()}${hint('Start with income actually available. Subtract each job once. If tax is named, gross income must become net income first.')}`;document.querySelectorAll('[data-fresh-model]').forEach(b=>b.onclick=()=>{if(b.dataset.freshModel==='correct'){work={...work,model:true};saveSession();feedback('That model gives every amount one job. Now calculate each remainder.','good');setTimeout(renderMission,350)}else miss('Check whether the model uses available income and subtracts every planned job exactly once.')});return}if(index<steps.length){const step=steps[index];$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · NEW BUDGET':'FAMILY PREVIEW · NOT DELAYED EVIDENCE'}</p><h3>${esc(step.prompt)}</h3>${storyCard(p.story)}${planFlow(steps,index)}${numberChoices(step.answer,step.decoys,'fresh-answer',freshMoneyChoiceIndex(track().id,'answer',index,ready,3))}${controls()}${hint('Use the previous remainder. Say which budget jobs have already been assigned and which are still waiting.')}`;document.querySelectorAll('[data-fresh-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.freshAnswer)===step.answer){work={...work,index:index+1,answers:[...answers,step.answer]};saveSession();feedback('That remainder keeps the budget balanced.','good');setTimeout(renderMission,350)}else miss('Check that this remainder subtracts the next planned job from the amount actually available.')});return}$('#activity').innerHTML=`<p class="eyebrow">PROVE THE COMPLETE BUDGET</p><h3>Final available amount: $${p.steps.at(-1)}</h3>${storyCard(p.story)}${textChoices(p.proof,p.decoys,'fresh-proof',freshMoneyChoiceIndex(track().id,'proof',0,ready,3))}${controls()}${hint('The proof must show each exact remainder and add all final jobs back to the available income.')}`;document.querySelectorAll('[data-fresh-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.freshProof==='correct'){feedback(ready?'You transferred the budgeting process to a fresh situation after a delay.':'Preview complete. Return later for fresh evidence.','good');complete(4,['budget','transfer'],false,!ready)}else miss('Reject a proof that ignores tax, duplicates money, or does not add back to available income.')})}
function renderComplete(i){const m=MONEY_CHAIN.missions[i];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${esc(m.title)}</h3><p>Your work is saved for ${learner==='a'?'Ella':'Mila'}.</p>${i<4?'<button class="primary" data-action="next">Continue →</button>':'<a class="primary" href="./" style="text-decoration:none">Return home</a>'}</div>`}
function renderMission(){const i=state.activeMission,m=MONEY_CHAIN.missions[i];if(sessionMissionId!==m.id)loadSession(m.id);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.replace('-',' ').toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i)){renderComplete(i);return}if(i===0)renderDiagnostic();else if(i===1)renderPlan();else if(i===2)renderDecision();else if(i===3)renderRepair();else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=MONEY_CHAIN.missions.map((m,i)=>`<button class="mission-button ${i===state.activeMission?'active':''} ${unlocked(i)?'':'locked'}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${esc(m.title)}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=Number(b.dataset.mission);sessionMissionId=null;save();render()})}
function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(MONEY_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path so evidence is not mixed.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankMoneyLearner(),track:e.target.value,family:state.family};sessionMissionId=null;save();render()}}
function renderEvidence(){const name=learner==='a'?'Ella':'Mila',labels={budget:'Build a balanced budget',tradeoff:'Explain a tradeoff',repair:'Repair overspending',transfer:'Fresh transfer'};$('#evidenceTitle').textContent=`${name}’s learning evidence`;$('#reviewBannerTitle').textContent=`Built for ${name} · waiting family review`;$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div class="evidence-item"><header><span>${v}</span><span>${state.evidence[k]==='independent'?'Independent':state.evidence[k]==='learning'?'Learning':'Not checked'}</span></header></div>`).join('')}
function renderFamily(){$('#helpNote').value=state.family.help;$('#explainNote').value=state.family.explain;$('#continueNote').value=state.family.continue}
function render(){ensureState();$('#learnerSelect').value=learner;renderTrack();renderNav();renderEvidence();renderFamily();renderMission()}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='start'){state.missions['money-start']={complete:true,score:state.diagnostic.score,completedAt:new Date().toISOString()};state.activeMission=1;sessionMissionId=null;save();render()}else if(a==='next'){state.activeMission=Math.min(4,state.activeMission+1);sessionMissionId=null;save();render()}else if(a==='hint'){hintLevel++;saveSession();renderMission()}else if(a==='preview'){state.previewFresh=true;save();render()}});
$('#learnerSelect').onchange=e=>{learner=e.target.value;state=readStore()[learner]||createBlankMoneyLearner();sessionMissionId=null;ensureState();saveLearnerChoice();render()};
for(const[id,key]of[['helpNote','help'],['explainNote','explain'],['continueNote','continue']])$('#'+id).addEventListener('input',e=>{state.family[key]=e.target.value;save()});
$('#resetPath').onclick=()=>{if(confirm(`Reset the money-choice review path for ${learner==='a'?'Ella':'Mila'}?`)){state=createBlankMoneyLearner();sessionMissionId=null;save();render()}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
ensureState();render();

